import { test, expect } from '@playwright/test';

test.describe('File Upload and Organization', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/upload');
  });

  test('should upload a file and create a folder', async ({ page }) => {
    await page.getByLabel('Upload File').setInputFiles('path/to/file.txt');
    await page.getByRole('button', { name: 'Create Folder' }).click();
    await page.getByLabel('Folder Name').fill('My Documents');
    await page.getByRole('button', { name: 'Save' }).click();

    const folder = await page.getByText('My Documents');
    await expect(folder).toBeVisible();
  });

  test('should verify file is inside the created folder', async ({ page }) => {
    await page.getByText('My Documents').click();
    const uploadedFile = await page.getByText('file.txt');
    await expect(uploadedFile).toBeVisible();
  });
});
